using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Globalization;

namespace DualMix.Core;

/// <summary>
/// Built-in localization (English default, Italian when Windows display language is Italian or explicitly selected).
/// Bindable from XAML via <c>{Binding [Key], Source={x:Static core:Loc.Instance}}</c> and updates live on change.
/// </summary>
public sealed class Loc : INotifyPropertyChanged
{
    public static Loc Instance { get; } = new();

    private static string? _cliOverride;
    private static LanguagePreference _preference = LanguagePreference.Auto;

    public static bool IsItalian { get; private set; } = DetectSystemItalian();

    public static event Action? LanguageChanged;
    public event PropertyChangedEventHandler? PropertyChanged;

    public string this[string key] => Get(key);

    public static bool DetectSystemItalian()
        => CultureInfo.CurrentUICulture.TwoLetterISOLanguageName.Equals("it", StringComparison.OrdinalIgnoreCase);

    public static void Initialize(LanguagePreference preference, string? cliOverride = null)
    {
        if (cliOverride != null) _cliOverride = cliOverride;
        _preference = preference;
        Apply();
    }

    public static void SetLanguage(LanguagePreference preference)
    {
        _preference = preference;
        _cliOverride = null;
        Apply();
    }

    private static void Apply()
    {
        bool next = _cliOverride?.ToLowerInvariant() switch
        {
            "it" => true,
            "en" => false,
            _ => _preference switch
            {
                LanguagePreference.Italian => true,
                LanguagePreference.English => false,
                _ => DetectSystemItalian(),
            }
        };
        if (next == IsItalian)
        {
            Instance.PropertyChanged?.Invoke(Instance, new PropertyChangedEventArgs("Item[]"));
            return;
        }
        IsItalian = next;
        Instance.PropertyChanged?.Invoke(Instance, new PropertyChangedEventArgs("Item[]"));
        LanguageChanged?.Invoke();
    }

    public static string T(string en, string it) => IsItalian ? it : en;

    public static string Get(string key) =>
        Table.TryGetValue(key, out var pair) ? (IsItalian ? pair.It : pair.En) : key;

    public static string Format(string key, params object?[] args) =>
        string.Format(IsItalian ? CultureInfo.GetCultureInfo("it-IT") : CultureInfo.InvariantCulture, Get(key), args);

