        ["Knob.Press"] = ("Press", "Premi"),
        ["Knob.CycleHeader"] = ("Switch function on the fly", "Cambiare funzione al volo"),
        ["Knob.DoublePress"] = ("Double-press knob", "Premi due volte la rotella"),
        ["Knob.DoublePressDesc"] = ("Two quick presses switch to the next function and show an on-screen indicator.", "Due pressioni rapide passano alla funzione successiva. Un indicatore a schermo mostra quella scelta."),
        ["Knob.CtrlPress"] = ("Ctrl + press knob", "Ctrl + premi la rotella"),
        ["Knob.CtrlPressDesc"] = ("Hold Ctrl and press the knob to cycle to the next function.", "Tieni premuto Ctrl e premi la rotella: passa alla funzione successiva."),
        ["Knob.Hotkey"] = ("Keyboard shortcut", "Scorciatoia da tastiera"),
        ["Knob.HotkeyDesc"] = ("Click the button and press your preferred key combination. Single keys (F1–F24, Pause, Ins…) also work.", "Clicca il pulsante e premi la combinazione che preferisci. Va bene anche un tasto solo (F1–F24, Pausa, Ins…)."),
        ["Knob.HotkeyTip"] = ("Click and press a new key combination (Esc cancels)", "Clicca e premi la nuova combinazione (Esc annulla)"),
        ["Knob.HotkeyResetTip"] = ("Reset to default shortcut", "Ripristina la scorciatoia predefinita"),
        ["Knob.CycleFunctions"] = ("Functions in cycle", "Funzioni nel ciclo"),
        ["Knob.BehaviorHeader"] = ("Behavior", "Comportamento"),
        ["Knob.StartFunc"] = ("Function at startup", "Funzione all'avvio"),
        ["Knob.StartFuncDesc"] = ("Every time DualMix starts (and at every PC boot), the knob resets to this function.", "A ogni avvio di DualMix (quindi a ogni accensione del PC) la rotella riparte da qui."),
        ["Knob.StartLast"] = ("Last used", "L'ultima usata"),
        ["Knob.MixPressMutes"] = ("On Mix mode, pressing knob mutes everything", "Sul mix, premere la rotella silenzia tutto"),
        ["Knob.MixPressMutesDesc"] = ("One press mutes (or unmutes) all sound. If disabled, one press resets the mix to Balanced.", "Una pressione toglie (o rimette) tutto l'audio. Se disattivato, la pressione riporta il mix su «Bilanciato»."),
        ["Knob.Enabled"] = ("DualMix handles knob", "DualMix usa la rotella"),
        ["Knob.EnabledDesc"] = ("When off, media keys and shortcuts are handled entirely by Windows.", "Se disattivato, rotella e scorciatoie tornano interamente a Windows."),
        ["Knob.CtrlAlt"] = ("Ctrl + turn: temporary alternate function", "Ctrl + gira: l'altra funzione, al momento"),
        ["Knob.CtrlAltDesc"] = ("Hold Ctrl while turning the knob to adjust Master Volume (when on Mix) or Mix (otherwise).", "Tenendo premuto Ctrl la rotella regola il volume generale quando è sul mix, e il mix in tutti gli altri casi."),
        ["Knob.Step"] = ("Step per detent", "Passo per scatto"),
        ["Knob.StepDesc"] = ("How much each step changes levels. Passing through center snaps once on Balanced.", "Quanto cambia ogni scatto della rotella. Passando dal centro il mix si ferma una volta su «Bilanciato»."),
        ["Knob.Invert"] = ("Invert direction", "Inverti direzione"),
        ["Knob.InvertDesc"] = ("Normal: left = more Game / quieter, right = more Chat / louder.", "Normalmente: sinistra = più Game / meno volume, destra = più Chat / più volume."),
        ["Knob.DedicatedKeys"] = ("Dedicated keys (advanced / QMK / VIA)", "Tasti dedicati (avanzato, con VIA)"),
        ["Knob.DedicatedKeysDesc"] = ("Map keys such as F13, F14, F15 in VIA/QMK: they always work regardless of the active knob function.", "Assegna con VIA tasti come F13, F14, F15: funzionano sempre, qualunque sia la funzione della rotella."),
