        // ---- Audio Page ----
        ["Audio.Title"] = ("Audio & devices", "Audio e dispositivi"),
        ["Audio.Subtitle"] = ("Choose your playback device and mixing engine. DualMix works on any sound card, speakers, USB headset, DAC, or with VB-CABLE virtual outputs.", "Scegli il dispositivo di ascolto e la modalità di mix. DualMix funziona su qualsiasi scheda audio, cuffie USB, DAC o con le uscite virtuali VB-CABLE."),
        ["Audio.OutputSection"] = ("Output", "Uscita"),
        ["Audio.RealOutput"] = ("Real playback device", "Dispositivo audio di ascolto"),
        ["Audio.RealOutputDesc"] = ("Where everything plays. On \"Automatic\", DualMix follows your active Windows playback device (speakers, headphones, DAC).", "Dove ascolti tutto. Con «Automatico» DualMix sceglie il tuo dispositivo di riproduzione attivo (cuffie, altoparlanti, DAC)."),
        ["Audio.AutoOption"] = ("Automatic ({0})", "Automatico ({0})"),
        ["Audio.AutoOptionEmpty"] = ("Automatic (Windows default device)", "Automatico (dispositivo predefinito di Windows)"),
        ["Audio.VirtualSection"] = ("Virtual outputs", "Uscite virtuali"),
        ["Audio.UseVirtual"] = ("Use DualMix virtual outputs (VB-CABLE)", "Usa le uscite virtuali DualMix Game e DualMix Chat"),
        ["Audio.UseVirtualDesc"] = ("Full hardware-style Game/Chat routing (requires VB-CABLE). Turn off for instant per-app mixing with no extra drivers.", "Routing completo con dispositivi virtuali (richiede VB-CABLE). Se disattivato, DualMix regola il volume per singola app senza driver."),
        ["Audio.DriverTitle"] = ("Virtual cable driver (VB-Audio)", "Driver dei cavi virtuali (VB-Audio)"),
        ["Audio.DriverStatus.None"] = ("Not installed. Automatic download installs official \"VB-CABLE\" for \"DualMix Chat\".", "Non installato. L'installazione scarica il driver ufficiale «VB-CABLE» per l'uscita «DualMix Chat»."),
        ["Audio.DriverStatus.One"] = ("1 virtual cable installed (\"{0}\"): DualMix Chat virtual, Game direct on output.", "1 cavo virtuale installato («{0}»): DualMix Chat virtuale, Game diretto sull'uscita."),
        ["Audio.DriverStatus.Two"] = ("2 virtual cables installed (\"{0}\" and \"{1}\").", "2 cavi virtuali installati («{0}» e «{1}»)."),
        ["Audio.DriverBtn.Install"] = ("Install", "Installa"),
        ["Audio.DriverBtn.Upgrade"] = ("Add 2nd cable…", "Aggiorna a 2 cavi…"),
        ["Audio.DriverBtn.Reconfigure"] = ("Reconfigure", "Riconfigura"),
        ["Audio.DriverBtn.Busy"] = ("Installing…", "Installo…"),
        ["Audio.DriverDialog.Title"] = ("Choose VB-CABLE A+B pack (.zip) from VB-Audio", "Seleziona il pacchetto VB-CABLE A+B (.zip) scaricato da VB-Audio"),
        ["Audio.DriverDialog.Filter"] = ("ZIP archive (*.zip)|*.zip", "Archivio ZIP (*.zip)|*.zip"),
        ["Audio.Driver.Working"] = ("Installing…", "Installazione in corso…"),
        ["Audio.Driver.Rejected"] = ("Incompatible driver removed", "Driver non compatibile rimosso"),
        ["Audio.Driver.Ready"] = ("Ready", "Pronto"),
        ["Audio.Driver.Failed"] = ("Failed", "Non riuscito"),
        ["Audio.GameDirect"] = ("Play Game directly on sound card", "Game diretto sulla scheda audio"),
        ["Audio.GameDirectDesc"] = ("Games bypass \"DualMix Game\" and go straight to your output: zero added latency. Mix controls game app volumes.", "I giochi saltano «DualMix Game» e suonano direttamente sulla scheda: latenza zero. Il bilanciamento agisce sul volume delle singole app."),
        ["Audio.SetDefaults"] = ("Set Windows default devices", "Imposta i dispositivi predefiniti di Windows"),
        ["Audio.DefaultsDual"] = ("Playback → DualMix Game · Communications → DualMix Chat", "Riproduzione → DualMix Game · Comunicazioni → DualMix Chat"),
        ["Audio.DefaultsSingle"] = ("Playback → {0} · Communications → DualMix Chat", "Riproduzione → {0} · Comunicazioni → DualMix Chat"),
        ["Audio.RouteApps"] = ("Auto-route apps to channels", "Indirizza le app automaticamente"),
        ["Audio.RouteAppsDesc"] = ("Each app is automatically routed to its channel endpoint. Leave Discord/TeamSpeak output set to \"Default\".", "Ogni app viene mandata all'uscita del suo canale. In Discord e TeamSpeak lascia l'uscita su «Predefinito»."),
        ["Audio.QualitySection"] = ("Quality", "Qualità"),
        ["Audio.Latency"] = ("Latency", "Latenza"),
        ["Audio.LatencyDesc"] = ("\"Low\" for competitive games; \"Safe\" if you hear crackles under heavy CPU load. Sound quality is identical.", "«Minima» per i giochi competitivi; «Sicura» se senti crepitii con il PC molto carico. La qualità non cambia."),
        ["Audio.Latency.Min"] = ("Low", "Minima"),
        ["Audio.Latency.Bal"] = ("Balanced", "Bilanciata"),
        ["Audio.Latency.Safe"] = ("Safe", "Sicura"),
        ["Audio.SignalPath"] = ("Signal path", "Percorso del segnale"),
        ["Audio.SignalPathUnavailable"] = ("Audio output unavailable", "Uscita non disponibile"),
        ["Audio.Signal.Bullet1"] = ("• Virtual outputs automatically match your sound card sample rate (and speaker layout 5.1/7.1 on DualMix Game): no format conversion.", "• Le uscite virtuali usano la stessa frequenza della scheda reale e «DualMix Game» anche gli stessi canali (5.1/7.1): nessuna conversione di formato."),
        ["Audio.Signal.Bullet2"] = ("• DualMix captures Windows' internal 32-bit floating-point mix before quantization and delivers it unchanged to your output.", "• DualMix cattura il mix interno di Windows a 32 bit in virgola mobile, prima di qualsiasi riduzione di bit, e lo consegna alla scheda nello stesso formato."),
        ["Audio.Signal.Bullet3"] = ("• At 100%, audio passes bit-for-bit at ×1.0 gain. No limiter, compressor, or EQ is applied.", "• Al 100% il segnale passa identico (×1,0). Nessun limitatore, compressore o equalizzatore."),
        ["Audio.Signal.Bullet4"] = ("• Tiny clock drift between virtual and hardware devices is compensated by a 160-tap sinc resampler (0.0000 dB gain error, < -130 dB noise floor).", "• La minuscola differenza di clock tra i dispositivi (pochi milionesimi) è compensata da un ricampionatore sinc a 160 punti (< -130 dB di rumore)."),
        ["Audio.WindowsSection"] = ("Windows", "Windows"),
        ["Audio.Ducking"] = ("Do not lower other sounds during calls", "Non abbassare gli altri suoni durante le chiamate"),
        ["Audio.DuckingDesc"] = ("By default Windows lowers other sounds by 80% when detecting a voice call, which breaks manual Game/Chat mixing.", "Windows normalmente riduce dell'80% tutto il resto quando rileva una chiamata: rovinerebbe il mix."),
        ["Audio.TroubleshootSection"] = ("Troubleshooting", "Risoluzione dei problemi"),
        ["Audio.RepairCard"] = ("Repair Windows audio service", "Ripara l'audio di Windows"),
        ["Audio.RepairCardDesc"] = ("Restarts the Windows Audio service if apps stop producing sound. Playback pauses briefly for a few seconds.", "Riavvia il servizio audio: serve se la scheda audio smette di suonare in tutte le app. L'audio si interrompe per qualche secondo."),

